# @@ the ODE: a harmonic oscillator as a first-order system
OMEGA = 2.0
def rhs(t, y: Arr) {
    return [y[1], -OMEGA * OMEGA * y[0]]
}
# @@ one classical Runge-Kutta step
def rk4_step(f, t, y: Arr, h) {
    k1 = f(t, y)
    k2 = f(t + h / 2, py_badd(y, h / 2 * k1))
    k3 = f(t + h / 2, py_badd(y, h / 2 * k2))
    k4 = f(t + h, py_badd(y, h * k3))
    return py_badd(y, h / 6 * py_badd(py_badd(py_badd(k1, 2 * k2), 2 * k3), k4))
}
# @@ integrate to t = 1 and compare with cos(2t)
T_END = 1.0
py_v1 = [10, 20, 40]
for py_i2 to 3 {
    steps = py_v1[py_i2]
    h = py_div_f(T_END, steps)
    y = [1.0, 0.0]
    t = 0.0
    for _ to steps {
        y = rk4_step(rhs, t, y, h)
        t += h
    }
    err = abs(y[0] - cos(OMEGA * T_END))
    print(fmt(steps + 0.0, "3d"), " steps: x(1) = ", fmt(y[0], ".10f"), ", error ", fmt(err, ".2e"), sep="")
}
# @@ checks
if not (err < 1e-06) {
    stop("AssertionError")
}
